    @Test
    /**
     * Full Create-Read-Update-Delete of a Employee, through a EmployeeTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on EmployeeTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on EmployeeTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new Employee.
     *
     * @return    Employee
     */
    public Employee testCreate() throws Throwable {
    Employee entity = null;

    LOGGER.info( "EmployeeTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Employee");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Employee" );

    try {
        entity = service.createEmployee( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getEmployeeId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Employee with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Employee.
     *
     * @return    Employee
     */
    public Employee testRead() throws Throwable {
    LOGGER.info( "EmployeeTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Employee" );

    Employee entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Employee with primary key" );
    msg.append( theId );

    try {
        entity = service.getEmployee( new EmployeeFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getEmployeeId();

        LOGGER.info( "-- Successfully found Employee " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Employee.
     *
     * @return    Employee
     */
    public Employee testUpdate() throws Throwable {
    LOGGER.info( "EmployeeTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Employee." );

    StringBuilder msg = new StringBuilder( "Failed to update a Employee : " );
    Employee entity = null;

    try {
        UpdateEmployeeCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setEmployeeId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Employee." );

        entity = service.updateEmployee( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Employee - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Employee.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "EmployeeTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Employee." );

    try {
        DeleteEmployeeCommand deleteCommand = new DeleteEmployeeCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Employee with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Employee with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Employees.
     *
     * @return    Collection
     */
    public List<Employee> testGetAll() throws Throwable {
    LOGGER.info( "EmployeeTest:testGetAll() - Retrieving Collection of Employees:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Employee : " );
    List<Employee> collection  = null;

    try {
        // call the static get method on the EmployeeService
        collection = service.getAllEmployee();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Employee currEntity  = null;
            Iterator<Employee> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getEmployeeId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

    public EmployeeTest setHandler( Handler handler ) {
    this.handler = handler;
    LOGGER.addHandler(handler);	// assign so the LOGGER can only output results to the Handler
    return this;
}


